  FORC(width - 1)
  {
    sum[c & 1] += ABS(img[0][c] - img[1][c + 1]);
    sum[~c & 1] += ABS(img[1][c] - img[0][c + 1]);
  }
  return 100 * log(sum[0] / sum[1]);
}

static void remove_trailing_spaces(char *string, size_t len) /* <=== remove_trailing_spaces:void(char*,ANY) */ 
{
